-- ADMIN KEEPS STARTING "WHAT'S INCLUDED" TEMPLATES FOR EACH SERVICE — Card Maker HYBRID part 2 (schema + a
-- PROPOSED seed).
--
-- Rulings (spec corpus DECISION_LOG, 17 Nov):
--   • 4906a9a8 "Variations become preset rows in step 3 'What's included', customised per service" — owner, on
--     Catering: "Type: Buffet / Plated · Food Tasting: 0 free or with Value (will increase) (PER PAX) · Tables and
--     Chairs · Service Booth · Staff · you need to research what we include per service. So we want to presetup
--     basic what's included that they would share". Amounts start blank (never invented) except a free tasting.
--   • 7596f63a "Admin can add and delete the starting templates for each service" — owner: "on template. allow us
--     to add and delete templates for each". Several per service; suppliers see Setnayan's first in Load and
--     cannot delete them.
--   • 17 Nov "no new admin page; two settings on the service panel" — the editor lives on Admin › Categories ›
--     the service's panel, as its "Quick Forms" section.
--   • 2026-11-11 "INCLUDED LINES HAVE NO PRICE" — so a template row can never carry an amount (CHECK below).
--   • 2026-11-18 "extend the app's one-page maker" — suppliers load a template into the shipped What's included.
--
-- RULE 0 — WHY A NEW TABLE AND NOT form_templates: form_templates (20271325118550, "Suggested for your service")
-- holds QUESTIONS a supplier asks a client, keyed by a leaf CATEGORY (category_form_suggestions). These rows are
-- what a card INCLUDES, keyed by one SERVICE, and they land in vendor_service_inclusions — a different fact with a
-- different reader. Folding them into form_templates would make one table answer two questions. Same admin
-- write pattern, same "a supplier's Load COPIES, an admin edit never rewrites a shop's card".
--
-- RLS at CREATE TABLE time — Pattern H (static reference data): every signed-in account reads; only an admin
-- writes (is_admin()). Admin › Categories writes with the service role, like form_templates.
BEGIN;

CREATE TABLE IF NOT EXISTS public.service_included_templates (
  template_id       UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  canonical_service TEXT NOT NULL
                    REFERENCES public.canonical_service_taxonomy(canonical_service) ON DELETE CASCADE,
  name              TEXT NOT NULL CHECK (char_length(btrim(name)) BETWEEN 1 AND 60),
  -- [{ "name": "Type", "kind": "choice", "options": ["Buffet", "Plated"], "basis": "per_pax" },
  --  { "name": "Tables and chairs", "kind": "plain", "basis": "none" }, …]
  --   kind  : plain = one line · choice = the couple picks one of `options`
  --   basis : none · flat · per_pax · tasting — HOW an option would add to the price once the supplier types an
  --           amount on their card. The template itself never holds the amount.
  rows              JSONB NOT NULL
                    CHECK (jsonb_typeof(rows) = 'array' AND jsonb_array_length(rows) BETWEEN 1 AND 30)
                    -- No prices, structurally: no row (and no option) may carry an amount of any name.
                    CHECK (NOT jsonb_path_exists(rows, 'strict $[*] ? (exists(@.price) || exists(@.amount) || exists(@.worth_php) || exists(@.price_php) || exists(@.amount_php) || exists(@.price_centavos))')),
  sort_order        INT NOT NULL DEFAULT 0,
  -- TRUE = drafted by Claude for the owner to review (the seed below). An admin edit or a new template is FALSE.
  is_proposal       BOOLEAN NOT NULL DEFAULT FALSE,
  source            TEXT NOT NULL DEFAULT 'admin'
                    CHECK (source IN ('admin', 'owner', 'app_fields', 'ph_norms', 'ph_norms_checked')),
  created_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by        UUID REFERENCES public.users(user_id) ON DELETE SET NULL
);

-- One name once per service (the Load list shows them by name).
CREATE UNIQUE INDEX IF NOT EXISTS service_included_templates_name_uidx
  ON public.service_included_templates (canonical_service, lower(btrim(name)));

CREATE INDEX IF NOT EXISTS service_included_templates_service_idx
  ON public.service_included_templates (canonical_service, sort_order);

ALTER TABLE public.service_included_templates ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS service_included_templates_read ON public.service_included_templates;
CREATE POLICY service_included_templates_read
  ON public.service_included_templates FOR SELECT
  TO authenticated
  USING (true);

DROP POLICY IF EXISTS service_included_templates_admin_write ON public.service_included_templates;
CREATE POLICY service_included_templates_admin_write
  ON public.service_included_templates FOR ALL
  TO authenticated
  USING ((SELECT public.is_admin()))
  WITH CHECK ((SELECT public.is_admin()));

REVOKE ALL ON public.service_included_templates FROM anon;
REVOKE INSERT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER ON public.service_included_templates FROM authenticated;
GRANT SELECT ON public.service_included_templates TO authenticated;

COMMENT ON TABLE public.service_included_templates IS
  'Setnayan''s starting "What''s included" templates per service (DECISION_LOG 2026-11-17, 4906a9a8 + 7596f63a). Admin adds, edits and deletes them on Admin › Categories › the service''s panel (Quick Forms). A supplier''s Load COPIES the rows into the card''s own What''s included; an admin edit never rewrites a card. No row carries a price (2026-11-11). is_proposal = drafted for the owner''s review, not yet reviewed.';

-- ── THE SEED — A PROPOSAL FOR THE OWNER, NOT A DECISION ─────────────────────────────────────────────────
-- 281 services, one "<service> basics" template each, every row is_proposal = TRUE.
-- Source of the words: spec corpus prototypes/whats_included_presets_2026-11-17.json (the 17 Nov draft the
-- owner asked for: "you need to research what we include per service"), then checked in this build against
-- search-result snippets of PH supplier pages — NO page could be opened in full (notes:
-- docs/card-maker-part-2/whats-included-presets-research-2026-11-17.md). `source` says where each came from:
--   owner = the owner's own Catering rows · app_fields = the app's existing detail fields for that service ·
--   ph_norms_checked = common PH practice, checked against search snippets · ph_norms = common PH practice,
--   NOT checked (no source covered it).
-- NO PRICES (2026-11-11 "an included line has no price"; enforced by the CHECK above). A choice row's
-- `basis` only says how an option would add to the price once the supplier types an amount on the card.
-- Seeded only where the service exists and is live; a re-run inserts nothing twice.
INSERT INTO public.service_included_templates (canonical_service, name, rows, source, is_proposal, sort_order)
SELECT v.canonical_service, v.name, v.rows, v.source, TRUE, 0
  FROM (VALUES
  ('reception_venue', 'Reception venue (other) basics', '[{"name": "Venue use", "kind": "choice", "basis": "flat", "options": ["Half day", "Full day"]}, {"name": "Tables and chairs", "kind": "plain", "basis": "none"}, {"name": "Basic lighting", "kind": "plain", "basis": "none"}, {"name": "Parking", "kind": "plain", "basis": "none"}, {"name": "Air conditioning", "kind": "plain", "basis": "none"}, {"name": "Bridal room", "kind": "plain", "basis": "none"}]'::jsonb, 'ph_norms_checked'),
